    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Boudin noir aux pommes, purée et oignons au miel', 'Boudin noir poêlé avec pommes, oignons caramélisés au miel et purée de pommes de terre', ds.id, 'SRC-032-D3',
    'Myko', 'editorial', 4, 35, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '7a1d2de82f517f79f80618ae6709cae1',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['caramélisé','sucré','profond','beurré']::text[],
    ARRAY['beurre','oignon_compoté','porc']::text[], ARRAY['protéine_fondante','tendre','contraste_léger']::text[],
    ARRAY['Boudin noir à cuire','Pomme fraîche']::text[], ARRAY['Sans boudin noir, le plat n''existe plus : la chair de sang poêlée en est l''axe et aucune autre charcuterie ne la remplace.','La pomme doit rester en morceaux identifiables et caramélisés ; réduite en compote lisse ou remplacée par de la pomme de terre, l''accord sucré-salé se défait.','Saisie brève puis feu doux : cuit à feu vif d''un bout à l''autre, le boyau éclate et le gras se perd dans la poêle.','Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle.']::text[],
    ARRAY['saisie','sauté','suer']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde 48 h à 4 °C en boîte fermée, boudin et pommes séparés, et se réchauffe à la poêle sur feu doux ou au four à 140 °C. Congélation déconseillée : le boudin cuit relargue son gras et devient granuleux, les pommes s''affaissent en rendant leur eau.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-032'), '{"variant_label":"Assiette complète : purée de pomme de terre et oignons confits au miel servis avec le boudin poêlé (marmiton.org).","rationale":"Deux choses changent réellement : les oignons sont poussés jusqu''au confit avec du miel, et une purée de pomme de terre montée au beurre rejoint l''assiette. Le miel accélère la coloration des oignons et les rend franchement sucrés, ce qui appuie l''accord avec le boudin mais rapproche le plat du dessert si l''on force la dose — et il brûle bien avant le sucre propre de l''oignon. Les sept cents grammes de pomme de terre font du plat un repas entier, sans pain ni féculent à côté, au prix d''une part nettement plus lourde et d''un troisième feu à mener de front.","operations":[{"op":"add","form":"Pomme de terre crue, épluchée","quantity":700,"unit":"g","role":"féculent","optional":false},{"op":"add","form":"Miel","quantity":25,"unit":"g","role":"condiment","optional":false},{"op":"set","form":"Beurre doux","quantity":90,"role":"matière grasse"}],"steps":[{"op":"replace","n":2,"instruction":"Épluchez 280 g d''oignons pour en obtenir 250 g nets, émincez-les finement et laissez-les fondre à couvert dans un tiers du beurre, sur feu très doux. Au bout de dix minutes, versez le miel, découvrez et poursuivez dix minutes en remuant souvent : ils doivent devenir sirupeux et brun clair sans jamais accrocher, le miel noircissant longtemps avant le sucre propre de l''oignon."},{"op":"insert","after":2,"instruction":"Épluchez 800 g de pommes de terre pour en obtenir 700 g nets, coupez-les en gros cubes et faites-les cuire vingt minutes à l''eau salée, départ à froid, jusqu''à ce que la pointe du couteau les traverse sans effort. Égouttez-les en réservant une louche d''eau de cuisson, écrasez-les au presse-purée avec un autre tiers du beurre et détendez avec l''eau réservée : au fouet ou au mixeur, l''amidon se délite et la purée devient élastique."},{"op":"replace","n":6,"instruction":"Salez et donnez deux tours de moulin à poivre au dressage. Étalez un large trait de purée dans des assiettes chaudes, posez le boudin par-dessus, ajoutez une cuillerée d''oignons au miel et rangez les quartiers de pomme caramélisés à côté. Nappez du beurre de cuisson resté dans la poêle : l''assiette se suffit alors à elle-même et n''appelle plus ni pain ni féculent."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
