  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Comptez quatre pommes à chair ferme, soit environ 450 g de fruits entiers : pelées, évidées et débarrassées des pépins, il en reste près de 320 g de chair. Détaillez-les en dés d''un centimètre plutôt qu''en quartiers — ils doivent sauter à la même allure que les rondelles de ratte — et arrosez-les aussitôt du jus de citron pour qu''ils gardent leur teinte claire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Brossez 600 g de rattes sans les peler, ces petites pommes de terre allongées tenant justement leur rondelle grâce à leur peau fine, et faites-les cuire vingt minutes à l''eau salée jusqu''à ce que la pointe du couteau entre sans forcer. Égouttez-les, laissez-les tiédir puis coupez-les en rondelles d''un demi-centimètre : jetées crues dans la poêle, elles brûleraient dehors bien avant d''être fondantes dedans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Épluchez 280 g d''oignons pour en obtenir 250 g nets, émincez-les finement et laissez-les fondre à couvert dans un tiers du beurre, sur feu très doux : une quinzaine de minutes suffisent pour qu''ils deviennent translucides puis prennent une couleur dorée, sans jamais accrocher au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans une seconde poêle, faites mousser la moitié du beurre restant et couchez-y les rondelles de ratte à plat. Laissez-les dorer cinq minutes sans y toucher, retournez-les, ajoutez les dés de pomme et les raisins secs, puis poursuivez cinq minutes à feu moyen : les raisins gonflent au contact du beurre chaud et suffisent à sucrer la poêlée. Réservez au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, qui donnent les 560 g de chair annoncés une fois les extrémités parées et le boyau fendu d''un coup de lame — retirez-le entièrement si vous préférez cuire la chair nue, gardez-le pour servir les tronçons entiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Essuyez la poêle qui a servi à la poêlée, chauffez-y le reste du beurre et posez le boudin sur feu vif juste le temps de le colorer, puis baissez immédiatement l''allure. Huit à dix minutes de cuisson douce en le tournant avec délicatesse suffisent : ne le piquez jamais, sous peine de voir le boyau se rompre et le gras s''échapper dans une poêle où plus rien ne viendra le boire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Salez, poivrez au moulin et mêlez les oignons fondus à la poêlée de rattes. Répartissez-la dans des assiettes chaudes et posez les tronçons de boudin dessus au tout dernier moment, sans les enfouir : posé trop tôt, il rend son gras et détrempe les rondelles dorées qui faisaient tout l''intérêt du plat.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-032-D4', 'recipe_family', 'Poêlée de rattes au boudin noir et aux raisins secs',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-032-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-032-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-032-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('bf583be64264f3769e5c3d349c2fdd0a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["caramélisé","sucré","profond","beurré"],"aroma_families":["beurre","oignon_compoté","porc"],"target_textures":["protéine_fondante","tendre","contraste_léger"],"signature_ingredients":["Boudin noir à cuire","Pomme fraîche"],"identity_guardrails":["Sans boudin noir, le plat n''existe plus : la chair de sang poêlée en est l''axe et aucune autre charcuterie ne la remplace.","La pomme doit rester en morceaux identifiables et caramélisés ; réduite en compote lisse ou remplacée par de la pomme de terre, l''accord sucré-salé se défait.","Saisie brève puis feu doux : cuit à feu vif d''un bout à l''autre, le boyau éclate et le gras se perd dans la poêle.","Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
