  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pommes au four farcies au boudin noir', 'pommes au four farcies au boudin noir', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pommes au four farcies au boudin noir', 'Pommes évidées farcies de boudin noir et oignons, cuites au four', ds.id, 'SRC-032-D5',
    'Myko', 'editorial', 4, 25, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '1a6bc88f93d94c7cb574c21d7110f50c',
    '{"sweet":4,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['pomme au four','sucré','profond','grillé']::text[],
    ARRAY['beurre','oignon_compoté','porc']::text[], ARRAY['chair fondante','farce grumeleuse','peau tendue']::text[],
    ARRAY['Boudin noir à cuire','Pomme fraîche']::text[], ARRAY['Sans boudin noir, le plat n''existe plus : la chair de sang en est l''axe et aucune autre charcuterie ne la remplace.','La pomme entière est ici le contenant, non la garniture : farcie dans un plat à gratin ou remplacée par un autre fruit, la préparation redevient un simple hachis de boudin aux oignons.','La pomme doit s''assouplir sans s''affaisser : trop cuite, elle s''ouvre en éventail et ne retient plus rien.','Le boyau se retire entièrement et la chair se grille nue : c''est cette accroche à la poêle qui rend au hachis ce que la cuisson au four lui retire.','Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle.']::text[],
    ARRAY['évidage','suer','grillade','farcissage','cuisson au four']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde 48 h à 4 °C en boîte fermée, boudin et pommes séparés, et se réchauffe à la poêle sur feu doux ou au four à 140 °C. Congélation déconseillée : le boudin cuit relargue son gras et devient granuleux, les pommes s''affaissent en rendant leur eau.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-032'), '{"variant_label":"Pommes entières évidées, passées au four puis garnies du hachis de boudin grillé et d''oignons fondus (750g.com).","rationale":"La pomme cesse d''être une garniture pour devenir le contenant : évidée, cuite au four, puis remplie du boudin grillé, écrasé et mêlé aux oignons fondus. Il faut deux fois plus de fruit — quatre pommes entières au lieu de quatre pommes détaillées — et le boudin, grillé nu puis haché, perd sa forme de tronçon et une part de son gras dans la poêle. La cuisson est plus longue, le service plus délicat, et le sucré du fruit domine nettement plus l''assiette que dans la poêlée d''origine.","operations":[{"op":"set","form":"Pomme fraîche","quantity":640,"role":"contenant"}],"steps":[{"op":"replace","n":1,"instruction":"Choisissez quatre pommes à chair ferme d''environ 200 g pièce, soit 800 g de fruits entiers, qui donneront les 640 g de chair annoncés une fois le cœur ôté. Lavez-les sans les peler, retirez le trognon au vide-pomme en creusant jusqu''aux deux tiers de la hauteur sans percer le fond, élargissez la cavité à la petite cuillère et badigeonnez-la du jus de citron pour qu''elle ne noircisse pas."},{"op":"replace","n":3,"instruction":"Rangez les pommes debout dans un plat, poudrez l''intérieur des cavités du sucre, posez une noisette du beurre restant sur chacune et enfournez 25 minutes à 180 °C. Elles doivent s''assouplir sans s''affaisser : trop cuite, une pomme s''ouvre en éventail et ne retient plus rien."},{"op":"replace","n":4,"instruction":"Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, pour les 560 g de chair annoncés. Fendez le boyau, retirez-le entièrement, puis grillez la chair nue cinq minutes à la poêle bien chaude en l''écrasant à la fourchette, jusqu''à ce qu''elle accroche par endroits. Hachez-la grossièrement au couteau une fois tiède."},{"op":"replace","n":5,"instruction":"Mêlez le hachis de boudin grillé aux oignons fondus, salez, poivrez, puis garnissez-en les cavités en tassant à la cuillère et en laissant un dôme dépasser. Remettez au four 10 minutes à 180 °C, le temps que la farce chauffe à cœur et que le dessus se croûte légèrement."},{"op":"replace","n":6,"instruction":"Servez les pommes brûlantes dans leur plat, arrosées du jus caramélisé qui a coulé au fond et d''un dernier tour de moulin à poivre. Elles ne supportent pas d''être dressées à l''assiette sans se briser : mieux vaut porter le plat entier et laisser chacun s''en servir."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
