  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Choisissez quatre pommes à chair ferme d''environ 200 g pièce, soit 800 g de fruits entiers, qui donneront les 640 g de chair annoncés une fois le cœur ôté. Lavez-les sans les peler, retirez le trognon au vide-pomme en creusant jusqu''aux deux tiers de la hauteur sans percer le fond, élargissez la cavité à la petite cuillère et badigeonnez-la du jus de citron pour qu''elle ne noircisse pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Épluchez 280 g d''oignons pour en obtenir 250 g nets, émincez-les finement et laissez-les fondre à couvert dans un tiers du beurre, sur feu très doux : une quinzaine de minutes suffisent pour qu''ils deviennent translucides puis prennent une couleur dorée, sans jamais accrocher au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Rangez les pommes debout dans un plat, poudrez l''intérieur des cavités du sucre, posez une noisette du beurre restant sur chacune et enfournez 25 minutes à 180 °C. Elles doivent s''assouplir sans s''affaisser : trop cuite, une pomme s''ouvre en éventail et ne retient plus rien.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, pour les 560 g de chair annoncés. Fendez le boyau, retirez-le entièrement, puis grillez la chair nue cinq minutes à la poêle bien chaude en l''écrasant à la fourchette, jusqu''à ce qu''elle accroche par endroits. Hachez-la grossièrement au couteau une fois tiède.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mêlez le hachis de boudin grillé aux oignons fondus, salez, poivrez, puis garnissez-en les cavités en tassant à la cuillère et en laissant un dôme dépasser. Remettez au four 10 minutes à 180 °C, le temps que la farce chauffe à cœur et que le dessus se croûte légèrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Servez les pommes brûlantes dans leur plat, arrosées du jus caramélisé qui a coulé au fond et d''un dernier tour de moulin à poivre. Elles ne supportent pas d''être dressées à l''assiette sans se briser : mieux vaut porter le plat entier et laisser chacun s''en servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-032-D5', 'recipe_family', 'Pommes au four farcies au boudin noir',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-032-D5', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-032-D5', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-032-D5', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1a6bc88f93d94c7cb574c21d7110f50c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":4,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["pomme au four","sucré","profond","grillé"],"aroma_families":["beurre","oignon_compoté","porc"],"target_textures":["chair fondante","farce grumeleuse","peau tendue"],"signature_ingredients":["Boudin noir à cuire","Pomme fraîche"],"identity_guardrails":["Sans boudin noir, le plat n''existe plus : la chair de sang en est l''axe et aucune autre charcuterie ne la remplace.","La pomme entière est ici le contenant, non la garniture : farcie dans un plat à gratin ou remplacée par un autre fruit, la préparation redevient un simple hachis de boudin aux oignons.","La pomme doit s''assouplir sans s''affaisser : trop cuite, elle s''ouvre en éventail et ne retient plus rien.","Le boyau se retire entièrement et la chair se grille nue : c''est cette accroche à la poêle qui rend au hachis ce que la cuisson au four lui retire.","Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Boudin noir aux pommes flambées au calvados', 'boudin noir aux pommes flambees au calvados', 'France', 'France',
     'meal', 'plat sauté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Boudin noir aux pommes flambées au calvados', 'Boudin noir et pommes sautés au beurre, flambés au calvados', ds.id, 'SRC-032-D6',
    'Myko', 'editorial', 4, 25, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', '0f13e65f5af9467025f9a0007f7f7143',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['caramélisé','sucré','profond','beurré']::text[],
    ARRAY['beurre','oignon_compoté','porc']::text[], ARRAY['protéine_fondante','tendre','contraste_léger']::text[],
    ARRAY['Boudin noir à cuire','Pomme fraîche']::text[], ARRAY['Sans boudin noir, le plat n''existe plus : la chair de sang poêlée en est l''axe et aucune autre charcuterie ne la remplace.','La pomme doit rester en morceaux identifiables et caramélisés ; réduite en compote lisse ou remplacée par de la pomme de terre, l''accord sucré-salé se défait.','Saisie brève puis feu doux : cuit à feu vif d''un bout à l''autre, le boyau éclate et le gras se perd dans la poêle.','Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle.']::text[],
    ARRAY['saisie','sauté','suer','flambage']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde 48 h à 4 °C en boîte fermée, boudin et pommes séparés, et se réchauffe à la poêle sur feu doux ou au four à 140 °C. Congélation déconseillée : le boudin cuit relargue son gras et devient granuleux, les pommes s''affaissent en rendant leur eau.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-032'), '{"variant_label":"Flambage au calvados sur les pommes caramélisées, ou mousse froide de boudin et de pomme montée en verrine (chefsimon.com).","rationale":"Le calvados versé hors du feu sur les quartiers déjà laqués puis enflammé brûle son alcool et laisse un sirop de pomme concentré, qu''on récupère au dressage. L''eau-de-vie appuie le fruit et tranche le gras du boudin ; mal conduite — versée sans flamber, ou laissée bouillir — elle laisse au contraire une amertume tenace. La seconde proposition de la même phrase, la mousse froide en verrine, n''est pas reprise ici : c''est une préparation froide et mixée, qui ne se décrit pas comme un écart à cette poêlée.","operations":[{"op":"add","form":"Calvados","quantity":40,"unit":"g","role":"alcool de flambage","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Dans une seconde poêle, faites mousser la moitié du beurre restant et couchez-y les quartiers de pomme à plat. Poudrez-les de sucre, laissez-les prendre couleur cinq minutes à couvert, retournez chaque morceau puis poursuivez à découvert jusqu''à ce que les faces soient laquées. Retirez alors la poêle du feu, versez le calvados et enflammez-le en écartant le visage : laissez la flamme mourir seule, elle emporte l''alcool et laisse le parfum du fruit, alors qu''une eau-de-vie simplement bouillie garde son amertume. Débarrassez aussitôt les quartiers et la totalité du sirop dans un plat creux tenu au chaud — la poêle servira ensuite au boudin, et tout ce qui y resterait partirait avec le coup de papier."},{"op":"replace","n":6,"instruction":"Salez et donnez deux tours de moulin à poivre au dressage. Répartissez les oignons fondus au fond d''assiettes chaudes, posez le boudin par-dessus et rangez les quartiers de pomme autour. Versez sur le tout le sirop réservé avec les fruits : c''est là que le calvados s''est concentré, et non dans le beurre où le boudin a cuit ensuite."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
