  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-032-D6', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0f13e65f5af9467025f9a0007f7f7143'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["caramélisé","sucré","profond","beurré"],"aroma_families":["beurre","oignon_compoté","porc"],"target_textures":["protéine_fondante","tendre","contraste_léger"],"signature_ingredients":["Boudin noir à cuire","Pomme fraîche"],"identity_guardrails":["Sans boudin noir, le plat n''existe plus : la chair de sang poêlée en est l''axe et aucune autre charcuterie ne la remplace.","La pomme doit rester en morceaux identifiables et caramélisés ; réduite en compote lisse ou remplacée par de la pomme de terre, l''accord sucré-salé se défait.","Saisie brève puis feu doux : cuit à feu vif d''un bout à l''autre, le boyau éclate et le gras se perd dans la poêle.","Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bouillabaisse du pêcheur', 'bouillabaisse du pecheur', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Bouillabaisse du pêcheur', 'Soupe de moules et pommes de terre dans un bouillon de poisson aux tomates râpées', ds.id, 'SRC-033-D1',
    'Myko', 'editorial', 4, 35, 45, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '96ee546589465c32345508c3703337f6',
    '{"sweet":1,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":4}'::jsonb, ARRAY['iodé','safran','tomate cuite','ail']::text[],
    ARRAY['marine','épice safranée','anisée','agrume']::text[], ARRAY['bouillon fluide et soyeux','pomme de terre fondante','chair de moule tendre']::text[],
    ARRAY['Sauce poisson','Moule commune crue','Safran']::text[], ARRAY['Sans safran, le bouillon perd sa robe orangée et son parfum : ce n''est plus une bouillabaisse mais une soupe de pommes de terre à la tomate.','Sans base marine — fond de poisson et coquillages — il ne reste qu''un ragoût de légumes ; l''iode est la colonne vertébrale du plat.','La garniture reste strictement marine et provençale : ni viande, ni condiment asiatique, quoi qu''en disent les relevés d''ingrédients aberrants.','Le bouillon ne doit jamais bouillir franchement, sous peine de troubler et de durcir les coquillages.']::text[],
    ARRAY['mijotage','pochage','réduction','infusion']::text[], ARRAY[]::text[], ARRAY['poisson','mollusques','sulfites']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C dans un récipient couvert, coquillages et bouillon ensemble ; ne réchauffer qu''une seule fois, à frémissement doux et sans ébullition. La congélation est déconseillée : le bouillon safrané la supporte, mais les moules deviennent caoutchouteuses et les pommes de terre farineuses à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-033'), '{"variant_label":"Version pêcheur : remplacer une partie des moules par des filets de poisson de roche déposés sur le bouillon et pochés hors du feu cinq minutes.","rationale":"La moitié des moules cède la place à des filets de rouget grondin, poisson de roche des mêmes fonds, posés sur le bouillon et pochés hors du feu. Le plat gagne en chair et en tenue ce qu''il perd en iode : moitié moins de coquillages, c''est aussi moitié moins de jus de moules pour saler et parfumer le bouillon, qu''il faut donc goûter de plus près avant de rectifier. Le pochage hors du feu est la seule façon de garder les filets entiers ; un frémissement, même léger, les défait en lambeaux en deux minutes.","operations":[{"op":"scale","form":"Moule commune crue","factor":0.5},{"op":"add","form":"Rouget grondin cru","quantity":500,"unit":"g","role":"protéine","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Compter 625 g de moules en coquille chez le poissonnier, moitié moins que dans la version toute marine : c''est le poids d''achat qui donne les 188 g de chair annoncés. Les gratter, tirer le byssus, les rincer à grande eau froide et jeter sans hésiter toute coquille fêlée ou qui refuse de se refermer lorsqu''on la tapote. Demander au même moment de lever en filets 1,3 kg de rougets grondins entiers : la tête cuirassée et l''arête de ce poisson de roche emportent près des deux tiers du poids, et il n''en reste que les 500 g de chair annoncés."},{"op":"replace","n":2,"instruction":"Verser le vin blanc dans un faitout, y jeter les moules, couvrir et monter à feu vif trois à quatre minutes en secouant une fois la casserole — moitié moins de coquillages s''ouvrent d''autant plus vite, et les oublier une minute de trop les racornit. Les retirer dès qu''elles bâillent, décoquiller les trois quarts et garder le reste en coquille pour le service. Filtrer le jus rendu à travers une passoire doublée d''un linge : c''est lui qui apportera le sel et l''iode, le sable doit rester dedans."},{"op":"replace","n":8,"instruction":"Couper le feu et déposer les filets de rouget grondin à plat sur le bouillon, sans les enfoncer. Couvrir et laisser pocher cinq minutes hors du feu : la chaleur retenue suffit à raffermir la chair, alors qu''un frémissement la déferait en lambeaux. Remettre alors la chair de moule et les coquilles réservées, goûter seulement à cet instant avant de saler — avec moitié moins de jus de coquillage, la base est nettement moins salée qu''à l''ordinaire — puis servir en assiette creuse en répartissant bouillon, pommes de terre, filets et coquillages."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
