  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Émietter le pain de campagne dans un bol et l''arroser du lait entier à peine tiédi. La mie doit avoir bu tout le liquide le temps que le reste se prépare ; on l''essorera ensuite entre les paumes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Partir d''un chou vert d''environ 1,6 kg tel qu''on l''achète chez le primeur. Ôter les feuilles extérieures fanées ou tachées et raccourcir le trognon au couteau : il reste à peu près les 1,2 kg de chou réellement comestible annoncés dans la liste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Immerger la tête entière dans un grand faitout d''eau salée maintenue à petits frémissements et compter un quart d''heure. Sortir le chou, le poser à l''envers dans une passoire et le laisser tiédir sans jamais l''écraser, sous peine de déchirer les feuilles.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Éplucher les légumes en tenant compte des pertes : comptez environ 300 g de carottes et 240 g d''oignons au poids d''achat pour retrouver les poids pelés de la liste. Tailler les carottes en rondelles épaisses, émincer finement la moitié des oignons et hacher l''autre moitié.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Passer la chair de brochet crue au hachoir à grille fine, ou la travailler longuement au couteau jusqu''à obtenir une pâte souple, en la palpant du bout des doigts pour n''y laisser aucune arête. Détailler la poitrine de porc au couteau en très petits dés, puis réunir le tout dans un grand saladier avec le porc haché, l''ail écrasé, le persil ciselé, l''oignon haché, les œufs battus et la mie pressée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Saler, poivrer, puis malaxer la farce à pleines mains une minute seulement, là où une farce de viande seule en demande deux : le poisson se défait et rend son eau si l''on insiste. Elle doit être homogène, nettement plus pâle qu''à l''ordinaire et à peine collante au creux de la paume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Écarter une à une les feuilles du chou tiédi, en progressant de l''extérieur vers le centre, jusqu''à dégager complètement le cœur. Détacher ce cœur, le hacher menu et le mêler à la farce, qui gagne ainsi le goût du chou.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Loger une grosse poignée de farce dans le creux laissé par le cœur, puis remonter les rangs de feuilles en glissant un peu de farce à chaque étage et en rabattant les feuilles au fur et à mesure, de façon à reformer une boule bien pleine et régulière.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Croiser deux longueurs de ficelle de cuisine sur le plan de travail, asseoir le chou reconstitué au centre et nouer les brins sur le dessus, assez serré pour que rien ne s''ouvre pendant la cuisson mais sans mordre dans les feuilles, qu''une ficelle trop tendue trancherait.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Beurrer largement le fond d''une cocotte, y étaler les lamelles d''oignon et les rondelles de carotte en lit régulier, poser le chou dessus, puis verser le bouillon de volaille et la tomate râpée le long des parois pour ne pas délaver le dessus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 11, 'Amener à frémissement à découvert, couvrir, puis tenir le feu au plus bas une heure trois quarts. La farce au brochet prend plus tôt qu''une farce de viande et se dessèche si on la pousse : dès qu''une lame glissée jusqu''au cœur en ressort chaude, c''est cuit. Arroser le dessus du chou avec le jus toutes les demi-heures et vérifier que rien n''accroche au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 12, 'Laisser reposer dix minutes hors du feu, couper les ficelles aux ciseaux, faire glisser le chou sur un plat creux et le partager en quartiers au grand couteau, chaque part nappée du jus de cuisson.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-038-D2', 'recipe_family', 'Chou farci de la Dombes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-038-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-038-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-038-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('07ecd1c3aec76071676da5557c4899a3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["viande braisée","chou fondant","bouillon de volaille","tomate cuite"],"aroma_families":["végétal cuit","gras animal","aromates verts"],"target_textures":["feuilles fondantes","farce moelleuse et serrée","jus court et nappant"],"signature_ingredients":["Chou vert frais","Chair de brochet crue","Porc haché cru","Poitrine de porc crue"],"identity_guardrails":["Les feuilles de chou vert entières doivent envelopper la farce et le chou être reconstitué en boule : émincé et mélangé à la viande, ce n''est plus un chou farci mais une potée","La farce reste une viande hachée grasse liée à la mie de pain et à l''œuf ; sans le gras de la poitrine de porc elle se dessèche et le plat perd son moelleux","La cuisson est un mijotage long à couvert dans un mouillement court, pas un rôtissage à sec"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de chou farci', 'gratin de chou farci', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Gratin de chou farci', 'Chou farci à la viande, terminé sous le gril avec une couche gratinée', ds.id, 'SRC-038-D3',
    'Myko', 'editorial', 6, 45, 75, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '5cf865cab7ea354eea7a893b2327f0b2',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['viande braisée','chou fondant','bouillon de volaille','tomate cuite']::text[],
    ARRAY['végétal cuit','gras animal','aromates verts']::text[], ARRAY['feuilles fondantes','farce moelleuse et serrée','jus court et nappant']::text[],
    ARRAY['Chou vert frais','Bœuf haché cru 15 % MG','Porc haché cru','Poitrine de porc crue']::text[], ARRAY['Les feuilles de chou vert entières doivent envelopper la farce et le chou être reconstitué en boule : émincé et mélangé à la viande, ce n''est plus un chou farci mais une potée','La farce reste une viande hachée grasse liée à la mie de pain et à l''œuf ; sans le gras de la poitrine de porc elle se dessèche et le plat perd son moelleux','La cuisson est un mijotage long à couvert dans un mouillement court, pas un rôtissage à sec']::text[],
    ARRAY['blanchiment','mijotage','farcissage']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C, dans son plat couvert d''un film ; réchauffer à 160 °C à couvert, puis découvrir dix minutes pour redonner du mordant à la surface. Congélation possible en parts jusqu''à 3 mois, mais les feuilles rendent de l''eau à la décongélation : décongeler au réfrigérateur, égoutter l''excédent de jus, puis repasser au four à découvert.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-038'), '{"variant_label":"Montage en gratin : couches alternées de feuilles et de farce dans un plat, nappées de tomate râpée et cuites une heure à 180 °C","rationale":"Le montage à plat supprime la reconstitution en boule et la ficelle, et ramène la cuisson à une heure de four contre deux heures de cocotte : c''est la version la plus courte des quatre. La surface gratine au lieu de mijoter, ce qui donne un dessus caramélisé que le chou farci classique n''a jamais, mais les feuilles supérieures s''assèchent si le jus ne remonte pas. La tomate monte à 600 g pour napper toute l''étendue du plat et le bouillon tombe à 200 ml, un gratin trop mouillé ne faisant jamais de croûte.","operations":[{"op":"set","form":"Tomate râpée","quantity":600},{"op":"set","form":"Bouillon de volaille","quantity":200}],"steps":[{"op":"replace","n":7,"instruction":"Écarter une à une les feuilles du chou tiédi, en progressant de l''extérieur vers le centre, jusqu''à dégager complètement le cœur. Aplatir au couteau la côte de chaque grande feuille pour qu''elle se couche à plat sans bomber, faute de quoi les couches ne se tiendront pas. Détacher le cœur, le hacher menu et le mêler à la farce, qui gagne ainsi le goût du chou."},{"op":"replace","n":8,"instruction":"Beurrer largement un plat à gratin et y étaler les lamelles d''oignon et les rondelles de carotte en lit régulier. Poser dessus un premier rang de feuilles qui se chevauchent et débordent un peu sur les bords, étaler le tiers de la farce en couche égale, couvrir de feuilles, et recommencer deux fois en terminant par des feuilles rabattues et lissées de la paume."},{"op":"remove","n":9},{"op":"replace","n":10,"instruction":"Napper toute la surface de tomate râpée, de façon qu''elle recouvre les feuilles sans les noyer, puis verser le bouillon de volaille le long des parois seulement : le dessus doit gratiner et non bouillir, et un plat trop mouillé ne fera jamais de croûte."},{"op":"replace","n":11,"instruction":"Enfourner à 180 °C pour une heure. À mi-cuisson, presser légèrement le dessus avec le dos d''une cuillère pour faire remonter le jus et arroser les feuilles supérieures, qui sinon se dessèchent avant que la farce ne soit prise ; si la surface fonce trop vite, la couvrir d''une feuille de papier cuisson pour le dernier quart d''heure."},{"op":"replace","n":12,"instruction":"Laisser reposer dix minutes hors du four, le temps que les couches se tiennent et cessent de glisser les unes sur les autres, puis découper en parts carrées à la spatule et servir chacune nappée du jus rassemblé au fond du plat."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
