  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-039-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b974299c5a37f2373653b495ca2a076c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["iodé","crémeux beurré","vin blanc réduit","échalote fondue"],"aroma_families":["marin","lacté","alliacé","grillé"],"target_textures":["chair nacrée et moelleuse","sauce nappante","croûte de chapelure croustillante"],"signature_ingredients":["Noix de Saint-Jacques crue","Crème fraîche liquide entière","Vin blanc sec","Chapelure de blé"],"identity_guardrails":["Sans noix de Saint-Jacques, ce n''est pas le plat : un autre poisson blanc en fait une simple coquille de poisson à la crème.","Les noix se saisissent très vite, une minute par face au plus : au-delà elles se rétractent et deviennent caoutchouteuses.","Le poids déclaré est celui des noix décoquillées — une coquille entière n''en donne qu''une trentaine de grammes."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Coquilles Saint-Jacques sauce Mornay', 'coquilles saint jacques sauce mornay', 'France', 'France',
     'meal', 'gratin', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Coquilles Saint-Jacques sauce Mornay', 'Noix de Saint-Jacques dans leur coquille, nappées d''une sauce Mornay et gratinées', ds.id, 'SRC-039-D2',
    'Myko', 'editorial', 4, 30, 25, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '51eb5c324dd2cee505e5db0dd71e6d72',
    '{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['iodé','crémeux beurré','vin blanc réduit','échalote fondue']::text[],
    ARRAY['marin','lacté','alliacé','grillé']::text[], ARRAY['chair nacrée et moelleuse','sauce nappante','croûte de chapelure croustillante']::text[],
    ARRAY['Noix de Saint-Jacques crue','Lait entier','Vin blanc sec','Chapelure de blé']::text[], ARRAY['Sans noix de Saint-Jacques, ce n''est pas le plat : un autre poisson blanc en fait une simple coquille de poisson à la crème.','Les noix se saisissent très vite, une minute par face au plus : au-delà elles se rétractent et deviennent caoutchouteuses.','Le poids déclaré est celui des noix décoquillées — une coquille entière n''en donne qu''une trentaine de grammes.']::text[],
    ARRAY['saisie','réduction','déglaçage','gratinage']::text[], ARRAY[]::text[], ARRAY['mollusques','poisson','lait','œuf','gluten','sulfites']::text[],
    'Monté mais non enfourné, le plat attend jusqu''à 12 h à 4 °C sous film. Cuit, il se garde 24 h au réfrigérateur et se réchauffe 6 à 7 minutes à 180 °C, jamais au micro-ondes. La chair crue parée ne dépasse pas 24 h posée sur un lit de glace. Congélation : acceptable pour la chair crue étalée à plat et bien épongée (2 mois), déconseillée pour le plat sauce comprise — une Mornay liée aux jaunes tranche encore plus vite qu''une sauce à la crème, le fromage se séparant du lait au réchauffage.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-039'), '{"variant_label":"Sauce Mornay au gruyère râpé et à la muscade, montée au lait, servie en petits poêlons individuels.","rationale":"Le lait remplace la crème et le gruyère prend le relais du gras : la sauce devient plus légère en bouche mais plus salée et plus franchement fromagère, et l''iode de la chair passe désormais au second plan. Un roux de 25 g ne tenait le liquide que parce que la crème l''épaississait déjà, d''où trente grammes de farine et une minute de cuisson supplémentaire. Le poêlon remplace la coquille : on y gagne un fond plus large et une croûte plus étendue, on y perd le geste de servir dans le coquillage, qui faisait la moitié de l''effet du plat, et il faut dix grammes de beurre de plus pour le graisser, la coquille s''en passant.","operations":[{"op":"substitute","form":"Crème fraîche liquide entière","with":"Lait entier","quantity":350,"unit":"ml","role":"liquide de sauce"},{"op":"set","form":"Farine de blé T55","quantity":30,"role":"liant"},{"op":"set","form":"Beurre doux","quantity":50,"role":"matière grasse"},{"op":"add","form":"Gruyère râpé","quantity":100,"unit":"g","role":"fromage","optional":false},{"op":"add","form":"Muscade moulue","quantity":1,"unit":"g","role":"épice","optional":false}],"steps":[{"op":"replace","n":2,"instruction":"Ouvrir chaque coquille en engageant une lame rigide contre la face plate, au niveau de la charnière, puis en rasant l''intérieur du couvercle pour trancher le muscle. Détacher la chair, ôter la frange grise et le petit nerf latéral, rincer très vite et éponger à fond. Les valves n''ont pas d''emploi ici : le montage se fait dans quatre petits poêlons de fonte ou de terre, beurrés de 10 g prélevés sur le beurre puis mis à tiédir près du four, dont le fond plus large donnera une croûte plus étendue."},{"op":"replace","n":5,"instruction":"Dans une casserole à part, fondre 25 g de beurre, pluie de farine, remuer une minute à feu doux : le mélange doit mousser sans blondir. Verser la réduction passée au tamis puis le lait tiédi en trois fois, en fouettant à chaque ajout. Laisser épaissir 6 à 7 minutes à petits bouillons — privée du gras qui la portait, la sauce demande un roux un peu plus fourni et une minute de plus pour napper le dos d''une cuillère."},{"op":"replace","n":6,"instruction":"Retirer du feu, attendre une minute, puis incorporer les jaunes d''œufs un par un au fouet — la sauce ne doit plus jamais bouillir, sous peine de grainer. Jeter le gruyère râpé en trois fois dans la chaleur restante en fouettant jusqu''à ce qu''il file sans se séparer, râper la muscade par-dessus, poivrer et ciseler le persil dedans. Goûter et n''ajuster le sel qu''après : la réduction et le fromage en apportent déjà beaucoup à eux deux."},{"op":"replace","n":7,"instruction":"Trancher les grosses pièces de chair en deux dans l''épaisseur, les répartir dans les poêlons tièdes sans les serrer, napper de sauce sans noyer, saupoudrer de chapelure et parsemer des 5 g de beurre restants en tout petits éclats."},{"op":"replace","n":8,"instruction":"Enfourner dans le haut d''un four préchauffé à 210 °C pour 8 à 10 minutes, le temps que la chapelure prenne couleur et que la surface boursoufle. S''arrêter dès que la croûte est dorée : au-delà, la chair se rétracte et devient élastique. Servir les poêlons brûlants, posés chacun sur une assiette doublée d''un rond de papier pour qu''ils ne glissent pas."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

