  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir à l''achat environ 1,3 kg de bulbes entiers avec leurs tiges et leurs plumets : c''est ce qu''il faut pour arriver aux 900 g de fenouil paré indiqués dans la liste. Sectionner les tiges à ras du bulbe, réserver quelques plumets pour la finition, et supprimer la côte extérieure dès qu''elle paraît fibreuse au toucher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Raccourcir la base terreuse au couteau sans creuser le cœur : c''est lui qui empêchera les morceaux de se défaire pendant la cuisson. Fendre chaque bulbe en deux dans la hauteur et s''en tenir là pour l''instant, la découpe fine venant après le passage à l''eau. Citronner aussitôt les faces tranchées pour qu''elles ne noircissent pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Porter une grande casserole d''eau salée à pleine ébullition et y plonger les demi-bulbes cinq minutes, pas davantage : il s''agit d''attendrir le cœur, pas de le cuire. Les sortir à l''écumoire, les laisser s''égoutter retournés sur un linge, puis les recouper en quartiers de deux à trois centimètres d''épaisseur. Les éponger à fond avant la poêle, sans quoi ils bouilliront dans leur propre eau au lieu de dorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer l''huile d''olive et le beurre ensemble dans une cocotte assez large pour recevoir tous les quartiers sur une seule couche. Y jeter l''oignon finement émincé et le laisser s''attendrir cinq minutes à feu modéré, jusqu''à ce qu''il perde son opacité, sans lui laisser prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Coucher les quartiers de fenouil sur leur face tranchée, bien à plat contre le fond, et les laisser dorer trois à quatre minutes seulement : une chair déjà attendrie prend couleur bien plus vite qu''une chair crue et brûlerait au temps de la version directe. Les retourner pour marquer l''autre face, puis glisser l''ail écrasé entre les morceaux au tout dernier moment afin qu''il parfume sans amertume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser le vin blanc sur le fond brûlant et gratter les sucs à la spatule ; laisser bouillonner une minute pour chasser l''alcool. Mouiller ensuite avec l''eau, qui doit monter à mi-hauteur des quartiers, éparpiller le thym et le sucre, puis assaisonner de sel et de poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Poser le couvercle et maintenir un frémissement paresseux une vingtaine de minutes, en retournant les quartiers une fois à mi-cuisson pour qu''ils s''imprègnent des deux côtés. Le blanchiment a pris de l''avance sur le braisage : goûter dès dix-huit minutes, car un fenouil déjà attendri passe du fondant à la charpie en quelques minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Retirer le couvercle et pousser le feu quelques minutes : le jus doit se resserrer jusqu''à napper les quartiers d''un sirop léger et brillant. Rectifier l''assaisonnement, disperser les plumets réservés et servir sans attendre, la sauce cuillérée par-dessus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-040-D1', 'recipe_family', 'Fenouil blanchi puis braisé',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-040-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-040-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-040-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('514d49c54182ed8a05f1f7f73a2776a2'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":1,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":2},"dominant_flavors":["anisé","citronné","sucré végétal"],"aroma_families":["anisée","agrume","herbacée"],"target_textures":["fondant","légèrement confit","jus sirupeux"],"signature_ingredients":["Fenouil frais","Vin blanc sec","Jus de citron frais"],"identity_guardrails":["Le fenouil doit être braisé en quartiers gardant leur cœur : émincé finement, il devient une fondue de fenouil et perd l''identité du plat.","La cuisson se fait à couvert dans un liquide court puis réduit ; rôti à sec au four, le résultat n''est plus un braisé.","L''acidité du vin blanc et du citron est structurante : sans elle le plat vire au légume sucré et l''amertume du bulbe ressort."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
