DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Fenouil braisé au citron', 'fenouil braise au citron', 'France', 'France',
     'meal', 'légume braisé', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Fenouil braisé au citron', 'Fenouil braisé dans un bouillon léger fortement acidulé au jus de citron, sans vin', ds.id, 'SRC-040-D2',
    'Myko', 'editorial', 4, 15, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', 'e793e15aa903af010f19143643bccd05',
    '{"sweet":3,"salty":2,"acidic":3,"bitter":1,"umami":1,"heat":0,"pungency":1,"richness":3,"freshness":3,"intensity":2}'::jsonb, ARRAY['anisé','citronné','sucré végétal']::text[],
    ARRAY['anisée','agrume','herbacée']::text[], ARRAY['fondant','légèrement confit','jus sirupeux']::text[],
    ARRAY['Fenouil frais','Jus de citron frais']::text[], ARRAY['Le fenouil doit être braisé en quartiers gardant leur cœur : émincé finement, il devient une fondue de fenouil et perd l''identité du plat.','La cuisson se fait à couvert dans un liquide court puis réduit ; rôti à sec au four, le résultat n''est plus un braisé.','Privé de déglaçage alcoolisé, le plat n''a plus que le citron pour tenir son acidité : le doubler et en garder la moitié pour le hors-feu n''est pas un détail mais la condition pour que le bulbe ne vire pas au légume sucré.']::text[],
    ARRAY['saisie','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se conserve 3 jours au réfrigérateur à 4 °C, dans une boîte hermétique et baigné de son jus de braisage ; réchauffer doucement à couvert avec une cuillère d''eau. La congélation est déconseillée : les fibres du fenouil éclatent au dégel et le légume rend son eau, donnant une texture filandreuse et un jus délavé.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-040'), '{"variant_label":"Sans alcool : supprimer le vin blanc sec, compenser par la même quantité d''eau et doubler le jus de citron frais en fin de réduction.","rationale":"Sans le déglaçage alcoolisé, le jus perd la charpente acide et légèrement amère qui tenait tête au sucre du bulbe ; le citron doublé la rétablit, mais elle devient plus pointue et plus courte en bouche. L''eau ne remplace le liquide que par le volume : elle n''apporte ni sucres ni tanins, si bien que la réduction finale nappe moins et met un peu plus de temps à se resserrer. En échange le plat devient servable aux enfants et perd ses sulfites.","operations":[{"op":"remove","form":"Vin blanc sec"},{"op":"set","form":"Eau","quantity":400,"unit":"ml","role":"mouillement"},{"op":"scale","form":"Jus de citron frais","factor":2}],"steps":[{"op":"replace","n":2,"instruction":"Raccourcir la base terreuse au couteau sans creuser le cœur : c''est lui qui empêchera les morceaux de se défaire pendant la cuisson. Fendre chaque bulbe en deux dans la hauteur, puis recouper en quartiers de deux à trois centimètres d''épaisseur selon la taille du légume. Les citronner aussitôt, mais avec la moitié du jus seulement : l''autre moitié part de côté jusqu''à la fin de cuisson, où elle rendra l''acidité qu''un déglaçage sans alcool ne donne plus."},{"op":"replace","n":5,"instruction":"Verser la moitié de l''eau sur le fond brûlant et gratter les sucs à la spatule, puis compléter avec le reste. Sans alcool pour dissoudre ce qui a attaché, ce seul mouillement doit tout faire : gratter franchement, jusqu''à ce que le fond redevienne clair. Le liquide monte à mi-hauteur des quartiers. Éparpiller le thym et le sucre, puis assaisonner de sel et de poivre."},{"op":"replace","n":7,"instruction":"Retirer le couvercle et pousser le feu quelques minutes : le jus doit se resserrer jusqu''à napper les quartiers d''un sirop léger et brillant, ce qui demande ici une minute ou deux de plus qu''à l''ordinaire. Verser alors hors du feu la moitié du jus de citron gardée pour la fin — c''est elle qui rend l''acidité perdue au déglaçage, et elle la garde d''autant mieux qu''elle n''a pas bouilli. Rectifier l''assaisonnement, disperser les plumets réservés et servir sans attendre."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

