  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir à l''achat environ 1,3 kg de bulbes entiers avec leurs tiges et leurs plumets : c''est ce qu''il faut pour arriver aux 900 g de fenouil paré indiqués dans la liste. Sectionner les tiges à ras du bulbe, réserver quelques plumets pour la finition, et supprimer la côte extérieure dès qu''elle paraît fibreuse au toucher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Raccourcir la base terreuse au couteau sans creuser le cœur : c''est lui qui empêchera les morceaux de se défaire pendant la cuisson. Fendre chaque bulbe en deux dans la hauteur, puis recouper en quartiers de deux à trois centimètres d''épaisseur selon la taille du légume. Les citronner aussitôt, mais avec la moitié du jus seulement : l''autre moitié part de côté jusqu''à la fin de cuisson, où elle rendra l''acidité qu''un déglaçage sans alcool ne donne plus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile d''olive et le beurre ensemble dans une cocotte assez large pour recevoir tous les quartiers sur une seule couche. Y jeter l''oignon finement émincé et le laisser s''attendrir cinq minutes à feu modéré, jusqu''à ce qu''il perde son opacité, sans lui laisser prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Coucher les quartiers de fenouil sur leur face tranchée, bien à plat contre le fond, et les laisser dorer sans y toucher cinq à six minutes. Les retourner pour colorer l''autre face, puis glisser l''ail écrasé entre les morceaux au tout dernier moment afin qu''il parfume sans amertume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser la moitié de l''eau sur le fond brûlant et gratter les sucs à la spatule, puis compléter avec le reste. Sans alcool pour dissoudre ce qui a attaché, ce seul mouillement doit tout faire : gratter franchement, jusqu''à ce que le fond redevienne clair. Le liquide monte à mi-hauteur des quartiers. Éparpiller le thym et le sucre, puis assaisonner de sel et de poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Poser le couvercle et maintenir un frémissement paresseux pendant une trentaine de minutes, en retournant les quartiers une fois à mi-cuisson pour qu''ils s''imprègnent des deux côtés. Le fenouil est prêt quand la pointe d''un couteau traverse le cœur sans résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer le couvercle et pousser le feu quelques minutes : le jus doit se resserrer jusqu''à napper les quartiers d''un sirop léger et brillant, ce qui demande ici une minute ou deux de plus qu''à l''ordinaire. Verser alors hors du feu la moitié du jus de citron gardée pour la fin — c''est elle qui rend l''acidité perdue au déglaçage, et elle la garde d''autant mieux qu''elle n''a pas bouilli. Rectifier l''assaisonnement, disperser les plumets réservés et servir sans attendre.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-040-D2', 'recipe_family', 'Fenouil braisé au citron',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-040-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-040-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-040-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e793e15aa903af010f19143643bccd05'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":2,"acidic":3,"bitter":1,"umami":1,"heat":0,"pungency":1,"richness":3,"freshness":3,"intensity":2},"dominant_flavors":["anisé","citronné","sucré végétal"],"aroma_families":["anisée","agrume","herbacée"],"target_textures":["fondant","légèrement confit","jus sirupeux"],"signature_ingredients":["Fenouil frais","Jus de citron frais"],"identity_guardrails":["Le fenouil doit être braisé en quartiers gardant leur cœur : émincé finement, il devient une fondue de fenouil et perd l''identité du plat.","La cuisson se fait à couvert dans un liquide court puis réduit ; rôti à sec au four, le résultat n''est plus un braisé.","Privé de déglaçage alcoolisé, le plat n''a plus que le citron pour tenir son acidité : le doubler et en garder la moitié pour le hors-feu n''est pas un détail mais la condition pour que le bulbe ne vire pas au légume sucré."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
