  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-041-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('9775a573edb4fe909b28e9811d143d9e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["bouillon de volaille","fromage affiné","légume crucifère doux"],"aroma_families":["bouillon","beurré","épices douces"],"target_textures":["bouquets fondants","sauce fluide et nappante","croûte gratinée"],"signature_ingredients":["Chou-fleur frais","Gruyère râpé","Bouillon de volaille"],"identity_guardrails":["Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.","C''est le roux beurre-farine qui fait la sauce, pas le liquide qu''on y verse : remplacer le lait par du bouillon reste un gratin, verser un jus de cuisson non lié n''en est plus un.","La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur au velouté."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
