    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-042-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-042-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-042-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d4b6680ab8d5315a97feae6e5552c0bf'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3},"dominant_flavors":["fumé","terreux","crème cuite"],"aroma_families":["fumé","herbacé sec","lacté"],"target_textures":["moitié veloutée et moitié restée grainée","lardon doré posé entier en surface","liaison crémeuse"],"signature_ingredients":["Lentille verte sèche, crue","Lardon fumé cru","Thym séché"],"identity_guardrails":["Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat","Seule la moitié de la casserole passe au mixeur ; tout mixer effacerait la lentille entière et ferait basculer le plat en soupe","Les lardons ne descendent jamais dans le mixeur : ils se posent entiers au dernier moment, faute de quoi leur fumé se dilue et la surface perd son contraste"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Lentilles corail au lard', 'lentilles corail au lard', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Lentilles corail au lard', 'Lentilles corail mijotées avec lardons fumés, carottes et oignons au thym', ds.id, 'SRC-042-D2',
    'Myko', 'editorial', 4, 20, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b0b09f1d343ca05380b0bd11ddf5a252',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['fumé','terreux']::text[],
    ARRAY['fumé','herbacé sec','végétal cuit']::text[], ARRAY['lentille délitée en purée','lardon doré aux arêtes croustillantes','jus épais lié par l''amidon du grain']::text[],
    ARRAY['Lentille corail sèche, crue','Lardon fumé cru','Thym séché']::text[], ARRAY['Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat','La corail se défait par nature et c''est tout le propos de la variante, mais elle interdit de dépasser vingt-cinq minutes, au-delà desquelles il ne reste qu''une bouillie sans relief','Le sel ne s''ajoute qu''en fin de cuisson et à petite dose, le lard ayant déjà salé le bouillon']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte fermée ; les lentilles boivent leur jus en refroidissant, rallonger d''un fond d''eau à la réchauffe douce. Congélation possible deux mois à condition de n''avoir pas mis la crème, celle-ci tranchant à la décongélation : la verser plutôt après réchauffage.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-042'), '{"variant_label":"Avec de la lentille corail, qui se délite en purée en une vingtaine de minutes et donne un plat plus fondant que grainé","rationale":"La corail est décortiquée : elle n''a plus de peau pour tenir le grain et se défait en purée, ce qui lie le jus toute seule et raccourcit la cuisson de quarante à vingt-cinq minutes. Le plat y perd sa mâche et le contraste entre la lentille ferme et le lardon fondant, qui faisait une partie de son intérêt. Il faut aussi mouiller moins — huit cents millilitres au lieu d''un litre — et remuer, la corail accrochant au fond dès qu''elle commence à se déliter.","operations":[{"op":"substitute","form":"Lentille verte sèche, crue","with":"Lentille corail sèche, crue","quantity":320,"unit":"g","role":"légumineuse"}],"steps":[{"op":"replace","n":1,"instruction":"Verser les lentilles dans une passoire et les rincer sous l''eau froide jusqu''à ce que l''eau cesse de blanchir : décortiquées, elles rendent beaucoup d''amidon en surface, et l''emporter dans la cocotte ferait mousser le bouillon. Aucun trempage — elles n''en ont pas besoin et se déferaient avant même d''avoir cuit."},{"op":"replace","n":5,"instruction":"Ajouter les lentilles égouttées et les remuer une minute dans les légumes gras : elles doivent se laquer et prendre le parfum du fond de cocotte avant tout liquide. Mouiller avec 800 ml d''eau froide seulement, un doigt au-dessus du niveau des grains : la corail boit moins longtemps que la verte et un litre donnerait une soupe."},{"op":"replace","n":6,"instruction":"Glisser le thym, le laurier et les clous de girofle, porter à petits bouillons puis baisser jusqu''au frémissement. Couvrir aux trois quarts et compter vingt minutes seulement, en remettant les lardons au bout de dix pour qu''ils parfument sans se dessécher. Passer la spatule plate sur le fond de temps à autre : la corail y accroche dès qu''elle commence à se défaire. Ne rien saler à ce stade."},{"op":"replace","n":7,"instruction":"Goûter : les grains ont perdu leur forme et s''écrasent en purée sous la langue, le jus s''étant épaissi de lui-même sans qu''on ait rien lié. Retirer le laurier et les clous de girofle, saler enfin, poivrer, et verser la crème pour arrondir encore si on le souhaite, en laissant frémir trois minutes de plus. Parsemer de persil ciselé au moment de porter à table."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
