  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-042-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b0b09f1d343ca05380b0bd11ddf5a252'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["fumé","terreux"],"aroma_families":["fumé","herbacé sec","végétal cuit"],"target_textures":["lentille délitée en purée","lardon doré aux arêtes croustillantes","jus épais lié par l''amidon du grain"],"signature_ingredients":["Lentille corail sèche, crue","Lardon fumé cru","Thym séché"],"identity_guardrails":["Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat","La corail se défait par nature et c''est tout le propos de la variante, mais elle interdit de dépasser vingt-cinq minutes, au-delà desquelles il ne reste qu''une bouillie sans relief","Le sel ne s''ajoute qu''en fin de cuisson et à petite dose, le lard ayant déjà salé le bouillon"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
