  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Verser les lentilles dans une passoire, les rincer sous l''eau froide et les étaler un instant sur la main pour écarter un éventuel gravillon. Aucun trempage : il ramollirait la peau et ferait éclater les grains pendant le mijotage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Éplucher les légumes et les tailler en dés de la taille d''un grain de lentille. Compter environ 210 g de carottes et 170 g d''oignon tels qu''ils sortent du cabas pour obtenir les poids nets indiqués une fois les épluchures parties ; l''ail se pèse gousses nues, soit trois à quatre gousses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chez le charcutier, demander un morceau de poitrine fumée d''environ 190 g : la couenne ôtée, il reste les 160 g de lardons qui entrent dans le plat. Les détailler en bâtonnets courts, puis les colorer à sec dans une cocotte à fond épais jusqu''à ce que la graisse ait rendu et que les arêtes soient dorées. Les débarrasser et jeter l''excédent de gras fondu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre la cocotte sur feu moyen avec 28 g de l''huile d''olive, les 12 g restants étant tenus de côté pour la fin, et y faire fondre carotte, oignon et échalote sans les brunir, une bonne poignée de minutes, jusqu''à ce qu''ils deviennent translucides. Ajouter l''ail haché et poursuivre trente secondes, le temps qu''il embaume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les lentilles égouttées et les remuer une minute dans les légumes gras : elles doivent se laquer et prendre le parfum du fond de cocotte avant tout liquide. Mouiller avec un litre d''eau froide, en ajoutant de quoi couvrir de deux doigts si besoin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Glisser le thym, le laurier et les clous de girofle, porter à petits bouillons puis baisser jusqu''au frémissement. Couvrir aux trois quarts et laisser aller trente-cinq à quarante minutes, en remettant les lardons à mi-parcours pour qu''ils parfument le bouillon sans se dessécher. Ne rien saler à ce stade.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Goûter un grain : il doit céder sous la dent tout en gardant sa forme. Retirer alors le laurier et les clous de girofle, saler enfin et donner un tour de moulin franc. Verser hors du feu l''huile d''olive réservée, à cru, en remuant une seule fois : chauffée, elle perdrait le fruité qui fait tout l''intérêt du geste. Parsemer largement de persil ciselé au moment de porter à table.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-042-D3', 'recipe_family', 'Lentilles au lard à l''huile d''olive',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
