  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Morue à la Brás', 'Morue effeuillée saisie avec des pommes de terre frites en fins bâtonnets et liée aux œufs brouillés', ds.id, 'SRC-043-D1',
    'Myko', 'editorial', 4, 40, 35, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '5867febc72431d6395a179926de05656',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['salin marin','oignon doux fondu','œuf crémeux','huile d''olive fruitée']::text[],
    ARRAY['marin','alliacé','herbacé','laurier']::text[], ARRAY['morue effeuillée en pétales','allumettes de pomme de terre dorées et encore fermes','liaison d''œuf à peine prise']::text[],
    ARRAY['Morue salée sèche','Pomme de terre crue, épluchée','Huile d''olive vierge extra']::text[], ARRAY['La morue salée sèche doit être dessalée vingt-quatre heures puis pochée avant d''être effeuillée à la main : sans ce dessalage, le plat est immangeable, et sans effeuillage il perd sa texture en pétales.','Les pommes de terre se taillent en allumettes et se frient crues : cuites d''abord puis sautées, elles s''écrasent dans la liaison et le plat devient une purée à l''œuf.','L''œuf est ajouté cru, hors ébullition et au dernier instant : dès qu''il prend en morceaux fermes, ce n''est plus une Brás mais une brouillade de morue.','L''huile d''olive vierge extra est le seul corps gras du plat : introduire du beurre ou de la crème ferait sortir la recette de son répertoire.']::text[],
    ARRAY['pochage','effeuillage','friture peu profonde','liaison aux œufs']::text[], ARRAY[]::text[], ARRAY['poisson','œuf']::text[],
    'Se mange à la sortie de la poêle : la liaison d''œuf continue de prendre tant que le plat est chaud et tourne sèche et granuleuse en quelques minutes. Un reste se garde 24 heures au réfrigérateur à 4 °C en boîte fermée, mais il se réchauffe très doucement à la poêle avec une cuillerée d''eau, jamais au micro-ondes qui achèverait de coaguler l''œuf. La congélation est à écarter : les allumettes frites ramollissent et l''œuf pris rend son eau à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-043'), '{"variant_label":"Version à la Brás : la morue effeuillée est sautée avec des pommes de terre taillées en allumettes puis liée aux œufs battus à feu très doux, sans passage au four.","rationale":"Le plat change entièrement de structure : il ne se monte plus en étages au four, il se lie à la poêle. Les pommes de terre passent de rondelles pochées à des allumettes frites, ce qui impose de partir de tubercules crus et fait presque doubler l''huile ; les œufs, durs et tranchés dans la base, deviennent crus et battus pour napper le mélange. On gagne une texture crémeuse et une fin de cuisson qui tient en dix minutes à la poêle — le dessalage de la veille, lui, reste dû —, on perd la croûte gratinée et toute possibilité de le préparer à l''avance : une Brás qui attend se dessèche.","operations":[{"op":"substitute","form":"Pomme de terre cuite","with":"Pomme de terre crue, épluchée","quantity":600,"unit":"g","role":"féculent"},{"op":"set","form":"Huile d''olive vierge extra","quantity":90},{"op":"set","form":"Œuf cru","quantity":250,"role":"liaison"}],"steps":[{"op":"replace","n":4,"instruction":"Peler environ 700 g de pommes de terre crues, dont il reste à peu près 600 g de chair épluchée, et les tailler en bâtonnets de la taille d''une allumette. Les rincer à grande eau froide pour emporter l''amidon de surface, puis les sécher longuement dans un torchon : une allumette humide ne dore pas, elle bout dans sa propre vapeur et retombe molle."},{"op":"replace","n":5,"instruction":"Casser les œufs dans un bol et les battre à la fourchette juste le temps de mêler blancs et jaunes, sans chercher à les faire mousser. Trop d''air et la liaison prendrait comme une omelette au lieu d''enrober la morue."},{"op":"replace","n":7,"instruction":"Verser le reste de l''huile dans une grande poêle, la chauffer jusqu''à ce qu''un bâtonnet grésille aussitôt, et frire les allumettes par petites poignées deux à trois minutes, jusqu''à ce qu''elles dorent et raidissent ; les égoutter au fur et à mesure sur du papier absorbant. Faire glisser l''oignon à l''ail de la sauteuse dans cette poêle, y ajouter les pétales de morue et les réchauffer une minute sans les défaire, puis rendre les allumettes au mélange au tout dernier instant, pour qu''elles n''aient pas le temps de ramollir."},{"op":"replace","n":8,"instruction":"Baisser au plus faible et verser les œufs battus d''un seul geste, en remuant sans arrêt à la spatule : ils doivent napper la morue et les allumettes d''une crème à peine prise, jamais se rassembler en morceaux fermes. Poivrer, goûter avant de saler, puis parsemer de persil ciselé et d''olives noires et servir immédiatement, la poêle continuant de cuire tant qu''elle est chaude."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

