  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-044-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c24cec3f535318566ed22cae9938507b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":4,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":2,"intensity":3},"dominant_flavors":["iodé","crème réduite","vineux","aillé"],"aroma_families":["marin","alliacé","herbacé","lacté"],"target_textures":["chair tendre et charnue","sauce nappante et lisse"],"signature_ingredients":["Moule commune crue","Vin blanc sec","Crème fraîche liquide entière","Persil frais"],"identity_guardrails":["Sans moules fraîches cuites dans leur coquille, le plat n''existe plus : la chair achetée décoquillée ne rend pas le jus qui fait la sauce","La crème vient après le vin, jamais à sa place : le mouillement reste un blanc sec, réduit et filtré, et une crème versée d''emblée sur les moules donne un plat plat et laiteux","Le jus se filtre avant d''être crémé : le sable qui traverse la sauce ne se rattrape plus","Le jus ne se sale pas d''avance : réduit puis crémé, il concentre tout le sel des coquillages","Le persil s''ajoute cru en fin de cuisson, jamais cuit avec les aromates"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Moules au cidre', 'moules au cidre', 'France', 'France',
     'meal', 'plat de fruits de mer', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Moules au cidre', 'Moules cuites à couvert dans du cidre brut avec ail et beurre', ds.id, 'SRC-044-D3',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f7b599fae384d3f438ba93d04951047a',
    '{"sweet":2,"salty":4,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":3,"intensity":3}'::jsonb, ARRAY['iodé','cidre fruité','aillé','beurré']::text[],
    ARRAY['marin','alliacé','herbacé','pomme']::text[], ARRAY['chair tendre et charnue','jus court et fluide']::text[],
    ARRAY['Moule commune crue','Cidre brut','Persil frais']::text[], ARRAY['Sans moules fraîches cuites dans leur coquille, le plat n''existe plus : la chair préparée à part ou décoquillée à l''avance perd le jus qui fait la marinière','Le mouillement doit rester un cidre brut, jamais un cidre doux ni un jus de pomme : le sucre d''un cidre demi-sec confit le jus et le fait basculer du côté du dessert','Le jus ne se sale pas d''avance : l''eau de mer relâchée par les coquillages est l''assaisonnement principal','Le persil s''ajoute cru en fin de cuisson, jamais cuit avec les aromates']::text[],
    ARRAY['réduction','pochage','cuisson à couvert']::text[], ARRAY[]::text[], ARRAY['mollusques','lait','sulfites','céleri']::text[],
    'Se mange dans la foulée. Les restes se gardent 24 heures maximum au réfrigérateur à 4 °C, décoquillés et immergés dans leur jus filtré, puis se réchauffent très brièvement à feu doux sans jamais bouillir. La congélation des moules cuites en coquille est déconseillée : la chair devient caoutchouteuse à la décongélation. Seul le jus de cuisson filtré se congèle bien, jusqu''à trois mois, et sert de base à une sauce ou à un risotto.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-044'), '{"variant_label":"Version normande : remplacer le vin blanc par du cidre brut","rationale":"Le cidre apporte une acidité plus ronde et un fond fruité là où le blanc sec tranchait, et le jus vire du citronné au pomme. Il porte aussi du sucre résiduel, même brut, ce qui demande une minute de bouillonnement de plus pour perdre son mordant de fruit cru et un tour de poivre supplémentaire à la fin pour rétablir l''équilibre. Le plat s''adoucit franchement : c''est un gain de gourmandise et une perte de nerf, et il accompagnera moins bien un pain très salé.","operations":[{"op":"substitute","form":"Vin blanc sec","with":"Cidre brut","quantity":500,"unit":"ml","role":"mouillement"}],"steps":[{"op":"replace","n":5,"instruction":"Mouiller avec le cidre brut, pousser le feu et laisser bouillonner trois minutes à découvert, une de plus qu''à l''ordinaire : le cidre porte toujours un reste de sucre qu''il faut cuire, sans quoi le bouillon garderait un goût de pomme crue au lieu du fond rond que l''on cherche."},{"op":"replace","n":8,"instruction":"Disperser le persil haché, donner un tour de poivre et mélanger une dernière fois avec précaution. Goûter le jus avant d''ajouter du sel : l''eau de mer rendue par les moules suffit le plus souvent, et comme le cidre a posé sa douceur sur l''ensemble, c''est plutôt un second tour de poivre qui remet le jus d''aplomb."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
