      WHERE ff.canonical_name_normalized = 'concentre de tomate' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Concentré de tomate', 60, 'g', 'required',
     'base de sauce', false, 9);

  INSERT INTO culinary.recipe_ingredient_requirements
