      WHERE ff.canonical_name_normalized = 'jarret de veau cru en tranches avec os' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Jarret de veau cru, en tranches avec os', 800, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
