    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Petits pois à la laitue au beurre', 'Petits pois avec laitue effilée dans un beurre monté, sans oignons grelots', ds.id, 'SRC-047-D3',
    'Myko', 'editorial', 4, 20, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', '2ecfc9f21748ac6e958536b9532caac1',
    '{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2}'::jsonb, ARRAY['douceur végétale du petit pois','beurre frais','oignon fondu']::text[],
    ARRAY['végétal frais','lacté beurré','herbacé anisé']::text[], ARRAY['petit pois fondant qui garde sa peau','laitue tombée et soyeuse','jus court et nappant']::text[],
    ARRAY['Petit pois surgelé','Laitue fraîche','Beurre doux']::text[], ARRAY['Sans la laitue braisée avec les pois, ce ne sont plus des petits pois à la française mais de simples petits pois au beurre.','Le mouillement doit rester un fond d''eau réduit en jus court et monté au beurre : noyer les légumes dans du bouillon fait perdre au plat sa concentration sucrée.','Ni crème ni farine : la liaison vient uniquement du beurre froid incorporé hors du feu.']::text[],
    ARRAY['mijotage','réduction','émulsion']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde 2 à 3 jours au réfrigérateur à 4 °C dans une boîte hermétique, et se réchauffe à couvert sur feu très doux avec une cuillère d''eau. La congélation est déconseillée : la laitue rend son eau et se défait, et les pois, déjà congelés une fois, s''écrasent à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-047'), '{"variant_label":"Sans lardons pour une garniture entièrement maigre, en compensant par une noisette de beurre supplémentaire à la fin.","rationale":"Le plat devient entièrement végétarien et perd d''un coup le sel fumé et la graisse de porc qui donnaient au fond de cuisson sa profondeur : ce qui reste est plus net, plus vert, franchement plus court en bouche. Les quinze grammes de beurre ajoutés rattrapent la texture du jus, qui nappe toujours, mais rien ne rattrape le fumé — il faut l''accepter plutôt qu''essayer de le remplacer. La garniture aromatique doit compenser par le temps ce qu''elle a perdu en gras, d''où un fondu d''oignon mené plus longuement.","operations":[{"op":"remove","form":"Lardon fumé cru"},{"op":"set","form":"Beurre doux","quantity":65,"role":"matière grasse","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Faites tiédir un tiers du beurre dans une cocotte à fond épais, à feu très doux, et jetez-y directement l''oignon et l''ail. Laissez-les fondre huit à dix minutes en remuant de temps en temps : privée de la graisse fumée qui parfumait le fond, la garniture aromatique doit donner seule tout ce qu''elle a, et cela demande du temps plus que du feu. L''oignon doit devenir translucide et sucré, jamais doré."},{"op":"replace","n":7,"instruction":"Découvrez et montez le feu une minute ou deux pour faire partir l''excédent de liquide, jusqu''à ce qu''il ne reste qu''un fond sirupeux au niveau des légumes. Coupez alors le feu et incorporez le beurre restant, très froid et coupé en dés, en imprimant à la cocotte un mouvement circulaire. Il y en a un tiers de plus que dans la recette d''origine et c''est voulu : il porte désormais seul le gras du plat, et c''est lui qui décide si le jus nappe ou reste de l''eau."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
