  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Parer le chou : d''une pomme achetée entière d''environ 1,1 kg, jeter les feuilles extérieures fatiguées et creuser le trognon à la pointe du couteau, ce qui laisse à peu près 800 g de feuilles utilisables. Fendre en quartiers, dégager la côte centrale trop dure et rincer à grande eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Immerger les quartiers de chou dans un grand volume d''eau bouillante non salée, compter deux à trois minutes dès que l''ébullition repart, puis les cueillir à l''écumoire et les rafraîchir sous le robinet froid. Les laisser s''égoutter, côte vers le bas : ce passage arrondit l''amertume et rend le plat plus digeste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Gratter les légumes-racines. Prévoir environ 600 g de carottes et 500 g de navets à l''achat pour obtenir respectivement 500 g et 400 g nets une fois épluchés et les bouts retirés. Débiter les carottes en gros tronçons de quatre centimètres, les navets en quartiers, de façon que tout cuise au même rythme.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Peler les oignons. En piquer un de tous les clous de girofle, en enfonçant chaque tête dans la chair jusqu''à ce qu''elle tienne seule ; couper l''autre en deux. Écraser les gousses d''ail d''un coup de paume, sans chercher à les peler complètement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Coucher les saucisses de Morteau et de Montbéliard entières au fond d''une grande cocotte, sans jamais les piquer, et les recouvrir de trois bons doigts d''eau froide. Ajouter l''oignon clouté, l''oignon fendu et l''ail, puis monter tout doucement en température.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dès que la surface frissonne, cueillir la mousse grise à la louche jusqu''à ce que le bouillon redevienne net. Maintenir ensuite un frémissement paresseux, couvercle posé de biais, pendant quarante-cinq minutes : une ébullition franche ferait éclater la peau des saucisses et troublerait le liquide. Ne rien saler à ce stade, la charcuterie fumée s''en charge.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Rincer les lentilles vertes à l''eau froide, sans les faire tremper. Les faire glisser dans le bouillon en même temps que les carottes et les navets, remuer une fois pour qu''elles ne s''agglutinent pas au fond, et laisser aller vingt-cinq minutes. Surveiller le niveau du liquide, qui descend beaucoup plus vite qu''à l''ordinaire, et compléter à l''eau bouillante dès que les légumes se découvrent. Ajouter alors les quartiers de chou blanchis et les pommes de terre pelées — compter à peu près 750 g de tubercules achetés pour les 600 g de chair attendus — et poursuivre trente minutes, jusqu''à ce que la lame d''un couteau traverse une pomme de terre sans buter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Goûter le bouillon avant toute correction : selon la salaison des saucisses, les 10 g de sel fin prévus seront de trop ou tout juste nécessaires, alors les incorporer par petites pincées successives. Donner un tour de moulin de poivre noir moulu et couper le feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Sortir les saucisses, les trancher en rondelles épaisses et les disposer au centre d''un plat creux bien chaud. Ranger les légumes autour par familles, puis verser les lentilles à la louche dans le creux du plat, où elles retiendront le bouillon qu''elles n''ont pas déjà bu. Servir aussitôt : le liquide restant est trop épais pour la soupière et se sert directement sur l''assiette, une louche par convive.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-050-D2', 'recipe_family', 'Potée auvergnate aux lentilles vertes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-050-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-050-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-050-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d8050162fcb8e5b8e0625219fedb9320'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":4,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["porc fumé","chou braisé","bouillon salé","légume-racine sucré"],"aroma_families":["fumé","épices chaudes","végétal cuit"],"target_textures":["légumes fondants","pomme de terre farineuse","saucisse ferme et juteuse","bouillon clair"],"signature_ingredients":["Chou vert frais","Saucisse de Morteau","Saucisse de Montbéliard","Pomme de terre cuite"],"identity_guardrails":["Sans chou, ce n''est plus une potée : c''est lui qui structure le plat et parfume le bouillon en retour.","La charcuterie doit être fumée et pochée entière ; remplacer Morteau et Montbéliard par une viande fraîche non fumée efface le goût de cochonnaille qui fait le plat.","Les légumes cuisent dans le bouillon des viandes, jamais dans une eau neuve : c''est cet échange qui distingue la potée d''un simple pot-au-feu de légumes.","Pas de liaison ni de crème : le bouillon reste clair et se sert tel quel."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Ratatouille confite au four', 'ratatouille confite au four', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Ratatouille confite au four', 'Légumes méditerranéens confits séparément puis réunis et confits au four à basse température', ds.id, 'SRC-051-D1',
    'Myko', 'editorial', 4, 30, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', '550f93e7d2947e8358d0cb39d27d3658',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','poivron confit','ail','huile d''olive']::text[],
    ARRAY['herbacé méditerranéen','végétal grillé','aillé']::text[], ARRAY['dés fondants gardant leur forme','sauce courte et nappante']::text[],
    ARRAY['Aubergine fraîche','Courgette fraîche','Poivron rouge frais','Tomate fraîche mûre','Huile d''olive vierge extra']::text[], ARRAY['Les quatre légumes d''été — aubergine, courgette, poivron, tomate — sont indissociables : en retirer un fait sortir du plat.','L''huile d''olive est le seul corps gras admis ; beurre ou crème déplacent la recette vers une autre famille.','Aucun bouillon ni liquide ajouté : la liaison vient de l''eau et des sucs rendus par les légumes eux-mêmes.','Ni viande ni féculent dans la cocotte, sous peine de basculer vers un ragoût ou une poêlée composée.']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Trois à quatre jours au réfrigérateur à 4 °C dans un contenant hermétique ; le goût se raffermit après une nuit de repos. Se congèle jusqu''à trois mois, mais les courgettes relâchent beaucoup d''eau à la décongélation : réchauffer à découvert pour faire évaporer le surplus avant de servir.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-051'), '{"variant_label":"Version confite au four : les légumes sont empilés crus en couches dans une cocotte en fonte, salés et parfumés entre chaque étage, puis cuits couvercle fermé une heure à four moyen, sans une goutte d''eau ajoutée.","rationale":"La cuisson change entièrement de nature : plus aucune saisie, les légumes entrent crus et confisent dans la vapeur qu''ils libèrent eux-mêmes sous le couvercle. On y gagne une heure sans surveillance et des dés uniformément fondants jusqu''au cœur ; on y perd la coloration de la sauteuse, ce goût de légume grillé que le confit ne produit jamais, et la possibilité de garder chaque légume distinct. L''huile descend de 80 à 60 g, faute des trois passages successifs qui en absorbaient à chaque tour.","operations":[{"op":"set","form":"Huile d''olive vierge extra","quantity":60}],"steps":[{"op":"replace","n":6,"instruction":"Chauffer le four à 160 °C. Frotter d''huile le fond et les parois d''une cocotte en fonte, puis y étaler la moitié des oignons émincés et la moitié de l''ail haché : placés dessous, ils fondent les premiers et parfument par en bas tout ce qui les surplombe."},{"op":"remove","n":7},{"op":"replace","n":8,"instruction":"Empiler les légumes crus par étages successifs — aubergine, courgette, poivron rouge, puis le poivron vert s''il entre dans la version choisie — en salant, poivrant et semant un peu de thym entre chaque couche, et en glissant le reste d''oignon et d''ail à mi-hauteur. Coiffer du concassé de tomate, compléter de la tomate râpée si les tomates manquent de maturité, poser les feuilles de laurier et arroser du reste d''huile. Ne rien mouiller : les légumes rendront à eux seuls tout le liquide dont la cocotte a besoin."},{"op":"replace","n":9,"instruction":"Fermer le couvercle et enfourner une heure pleine sans jamais soulever. La vapeur retenue sous la fonte fait tout le travail : les dés s''affaissent lentement dans leur propre jus au lieu de rissoler, et chaque étage se parfume de celui qui le surmonte."},{"op":"replace","n":10,"instruction":"Sortir la cocotte, ôter le couvercle et les feuilles de laurier, puis remettre dix à quinze minutes à découvert si le fond baigne encore. Mélanger d''un geste large en soulevant par-dessous plutôt qu''en remuant, pour ne pas réduire les étages en purée, rectifier le sel et laisser tiédir : la ratatouille confite se sert à peine chaude, ou réchauffée le lendemain, jamais brûlante."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
