  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les aubergines achetées entières, environ 350 g sur la balance, ôter le pédoncule sans les peler, les débiter en tranches d''un centimètre puis recouper ces tranches en cubes : il reste à peu près 335 g de chair prête à cuire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Traiter les courgettes de la même façon, peau comprise, en visant des dés du même calibre que ceux d''aubergine ; 350 g bruts donnent environ 335 g une fois les deux extrémités supprimées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Fendre les poivrons, retirer la queue, les côtes blanches et les pépins — deux poivrons rouges pesés 350 g à l''achat laissent près de 300 g de chair — puis les tailler en carrés d''un centimètre. Réserver le poivron vert paré de la même manière s''il entre dans la version choisie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Éplucher et émincer finement les oignons, en comptant 340 g bruts pour 300 g nets, écraser les gousses d''ail du plat de la lame puis les hacher menu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Inciser la base des tomates d''une croix, les plonger dix secondes dans l''eau frémissante, les rafraîchir aussitôt, retirer peau et graines : 550 g de tomates bien mûres fournissent environ 500 g de pulpe à concasser grossièrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Chauffer un tiers de l''huile dans une large sauteuse et y colorer les dés d''aubergine à feu vif, en remuant le moins possible pour qu''ils dorent sans se défaire, puis les débarrasser dans un plat creux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Répéter l''opération avec les courgettes, puis avec les poivrons, en versant un peu d''huile à chaque tour ; chaque légume doit conserver du mordant au cœur et attendre à part, hors de la sauteuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Dans le même récipient, faire tomber les oignons à feu doux jusqu''à ce qu''ils deviennent translucides, ajouter l''ail une minute, puis la pulpe de tomate, le thym, le laurier, le sel et le poivre ; laisser réduire à découvert un quart d''heure, en complétant avec la tomate râpée si les tomates manquent de maturité.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Remettre tous les légumes réservés dans la sauteuse avec le jus qu''ils ont rendu, mélanger avec précaution pour ne pas les écraser, couvrir et laisser mijoter à tout petit feu une vingtaine de minutes. Dix minutes avant la fin, semer les olives noires dénoyautées et taillées en rondelles, puis découvrir pour laisser le fond réduire : jetées plus tôt, elles rendraient toute leur saumure dans la sauce et le plat serait salé sans retour possible.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Retirer les feuilles de laurier et goûter avant de saler : les olives ont déjà porté leur part et il en faut souvent moins que prévu. Laisser reposer hors du feu au moins un quart d''heure ; cette ratatouille se sert tiède, ou réchauffée le lendemain, jamais brûlante.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-051-D3', 'recipe_family', 'Ratatouille aux olives noires',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-051-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-051-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-051-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('800ed1e3bd643f6d2867f1a9953d6c93'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","poivron confit","ail","huile d''olive"],"aroma_families":["herbacé méditerranéen","végétal grillé","aillé"],"target_textures":["dés fondants gardant leur forme","sauce courte et nappante"],"signature_ingredients":["Aubergine fraîche","Courgette fraîche","Poivron rouge frais","Tomate fraîche mûre","Huile d''olive vierge extra"],"identity_guardrails":["Les quatre légumes d''été — aubergine, courgette, poivron, tomate — sont indissociables : en retirer un fait sortir du plat.","L''huile d''olive est le seul corps gras admis ; beurre ou crème déplacent la recette vers une autre famille.","Aucun bouillon ni liquide ajouté : la liaison vient de l''eau et des sucs rendus par les légumes eux-mêmes.","Ni viande ni féculent dans la cocotte, sous peine de basculer vers un ragoût ou une poêlée composée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
