  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Ratatouille au basilic', 'Ratatouille provençale avec basilic frais ajouté en finition hors du feu', ds.id, 'SRC-051-D4',
    'Myko', 'editorial', 4, 30, 55, 'facile',
    NULL, NULL,
    'B', 'candidate', 'd77cf179746dcd5f9f9b62db8f54cce5',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','poivron confit','ail','huile d''olive']::text[],
    ARRAY['herbacé méditerranéen','végétal grillé','aillé']::text[], ARRAY['dés fondants gardant leur forme','sauce courte et nappante']::text[],
    ARRAY['Aubergine fraîche','Courgette fraîche','Poivron rouge frais','Tomate fraîche mûre','Huile d''olive vierge extra']::text[], ARRAY['Les quatre légumes d''été — aubergine, courgette, poivron, tomate — sont indissociables : en retirer un fait sortir du plat.','L''huile d''olive est le seul corps gras admis ; beurre ou crème déplacent la recette vers une autre famille.','Aucun bouillon ni liquide ajouté : la liaison vient de l''eau et des sucs rendus par les légumes eux-mêmes.','Ni viande ni féculent dans la cocotte, sous peine de basculer vers un ragoût ou une poêlée composée.']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Trois à quatre jours au réfrigérateur à 4 °C dans un contenant hermétique ; le goût se raffermit après une nuit de repos. Se congèle jusqu''à trois mois, mais les courgettes relâchent beaucoup d''eau à la décongélation : réchauffer à découvert pour faire évaporer le surplus avant de servir.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-051'), '{"variant_label":"Basilic ciselé jeté hors du feu au moment de servir, à la place ou en plus du thym.","rationale":"Le thym séché sort de la liste et vingt grammes de basilic frais le remplacent, jetés hors du feu : la ratatouille perd sa note résineuse de garrigue, cuite et fondue dans la sauce, et gagne un parfum vert et volatil posé par-dessus. Le changement est plus grand qu''il n''y paraît, parce que le basilic ne cuit pas — il n''imprègne rien et il faut le disperser au dernier moment. Le plat ne supporte plus le réchauffage du lendemain sans qu''on refasse la finition avec des feuilles fraîches.","operations":[{"op":"remove","form":"Thym séché"},{"op":"add","form":"Basilic frais","quantity":20,"unit":"g","role":"finition","optional":false}],"steps":[{"op":"replace","n":8,"instruction":"Dans le même récipient, faire tomber les oignons à feu doux jusqu''à ce qu''ils deviennent translucides, ajouter l''ail une minute, puis la pulpe de tomate, le laurier, le sel et le poivre ; laisser réduire à découvert un quart d''heure, en complétant avec la tomate râpée si les tomates manquent de maturité. Aucune herbe séchée n''entre ici : la sauce doit rester franche et sans note résineuse pour que le parfum vert de la finition arrive intact."},{"op":"replace","n":10,"instruction":"Retirer les feuilles de laurier, rectifier l''assaisonnement et laisser tiédir une dizaine de minutes hors du feu. Ciseler alors le basilic frais et le disperser sur le plat sans le mélanger longuement : posé sur une ratatouille encore brûlante ou remué trop tôt, il noircit et perd en quelques minutes tout ce qu''il apportait."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

