  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les aubergines achetées entières, environ 350 g sur la balance, ôter le pédoncule sans les peler, les débiter en tranches d''un centimètre puis recouper ces tranches en cubes : il reste à peu près 335 g de chair prête à cuire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Traiter les courgettes de la même façon, peau comprise, en visant des dés du même calibre que ceux d''aubergine ; 350 g bruts donnent environ 335 g une fois les deux extrémités supprimées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Fendre les poivrons, retirer la queue, les côtes blanches et les pépins — deux poivrons rouges pesés 350 g à l''achat laissent près de 300 g de chair — puis les tailler en carrés d''un centimètre. Réserver le poivron vert paré de la même manière s''il entre dans la version choisie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Éplucher et émincer finement les oignons, en comptant 340 g bruts pour 300 g nets, écraser les gousses d''ail du plat de la lame puis les hacher menu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Inciser la base des tomates d''une croix, les plonger dix secondes dans l''eau frémissante, les rafraîchir aussitôt, retirer peau et graines : 550 g de tomates bien mûres fournissent environ 500 g de pulpe à concasser grossièrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Chauffer un tiers de l''huile dans une large sauteuse et y colorer les dés d''aubergine à feu vif, en remuant le moins possible pour qu''ils dorent sans se défaire, puis les débarrasser dans un plat creux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Répéter l''opération avec les courgettes, puis avec les poivrons, en versant un peu d''huile à chaque tour ; chaque légume doit conserver du mordant au cœur et attendre à part, hors de la sauteuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Dans le même récipient, faire tomber les oignons à feu doux jusqu''à ce qu''ils deviennent translucides, ajouter l''ail une minute, puis la pulpe de tomate, le laurier, le sel et le poivre ; laisser réduire à découvert un quart d''heure, en complétant avec la tomate râpée si les tomates manquent de maturité. Aucune herbe séchée n''entre ici : la sauce doit rester franche et sans note résineuse pour que le parfum vert de la finition arrive intact.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Remettre tous les légumes réservés dans la sauteuse avec le jus qu''ils ont rendu, mélanger avec précaution pour ne pas les écraser, couvrir et laisser mijoter à tout petit feu une vingtaine de minutes, puis découvrir une dizaine de minutes si le fond reste trop liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Retirer les feuilles de laurier, rectifier l''assaisonnement et laisser tiédir une dizaine de minutes hors du feu. Ciseler alors le basilic frais et le disperser sur le plat sans le mélanger longuement : posé sur une ratatouille encore brûlante ou remué trop tôt, il noircit et perd en quelques minutes tout ce qu''il apportait.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-051-D4', 'recipe_family', 'Ratatouille au basilic',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-051-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-051-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-051-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d77cf179746dcd5f9f9b62db8f54cce5'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","poivron confit","ail","huile d''olive"],"aroma_families":["herbacé méditerranéen","végétal grillé","aillé"],"target_textures":["dés fondants gardant leur forme","sauce courte et nappante"],"signature_ingredients":["Aubergine fraîche","Courgette fraîche","Poivron rouge frais","Tomate fraîche mûre","Huile d''olive vierge extra"],"identity_guardrails":["Les quatre légumes d''été — aubergine, courgette, poivron, tomate — sont indissociables : en retirer un fait sortir du plat.","L''huile d''olive est le seul corps gras admis ; beurre ou crème déplacent la recette vers une autre famille.","Aucun bouillon ni liquide ajouté : la liaison vient de l''eau et des sucs rendus par les légumes eux-mêmes.","Ni viande ni féculent dans la cocotte, sous peine de basculer vers un ragoût ou une poêlée composée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Riz pilaf au curry', 'riz pilaf au curry', 'France', 'France',
     'meal', 'accompagnement', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Riz pilaf au curry', 'Riz pilaf nacré à l''oignon et parfumé au curry avant absorption du bouillon', ds.id, 'SRC-052-D1',
    'Myko', 'editorial', 4, 10, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', '5533d8d77a91adc9b35ba981ad4c32a3',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2}'::jsonb, ARRAY['bouillon de volaille','oignon fondu','beurre']::text[],
    ARRAY['alliacé','lacté','céréalier']::text[], ARRAY['grains égrenés et détachés','riz fondant sans être collant']::text[],
    ARRAY['Riz cru','Bouillon de volaille','Oignon jaune cru']::text[], ARRAY['Le riz doit être nacré dans le corps gras avant tout mouillement : sans cette étape d''enrobage, on obtient du riz bouillonné, plus un pilaf.','Le liquide est versé chaud et en une seule fois, à environ une fois et demie le volume du riz, puis le plat cuit à couvert sans être remué : remuer libère l''amidon et fait glisser le plat vers le risotto.','Le mouillement se fait au bouillon et non à l''eau nue : c''est lui qui porte tout l''assaisonnement du grain.']::text[],
    ARRAY['nacrage','mijotage']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se conserve 2 à 3 jours au réfrigérateur à 4 °C dans une boîte hermétique, refroidi rapidement après le service. Réchauffer à couvert avec une à deux cuillerées de bouillon ou d''eau pour réhydrater les grains. La congélation est possible 2 mois en portions étalées à plat, mais le riz ressort un peu plus mou et moins égrené au décongelage.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-052'), '{"variant_label":"Pilaf au curry : ajouter une cuillerée de curry en poudre au moment de l''assaisonnement, sur les oignons blondis, comme le fait 750g.com.","rationale":"Six grammes de curry en poudre torréfiés dans le corps gras teintent le riz et lui donnent un fond épicé chaud que le bouillon de volaille seul ne porte pas. La conduite de l''oignon change avec eux : il faut le laisser blondir aux bords au lieu de le garder translucide, sans quoi la poudre n''a pas de gras assez chaud pour s''ouvrir. Le pilaf cesse d''être un accompagnement neutre et impose sa couleur à ce qu''on servira avec.","operations":[{"op":"add","form":"Curry en poudre","quantity":6,"unit":"g","role":"épice","optional":false}],"steps":[{"op":"replace","n":2,"instruction":"Dans une sauteuse large à fond épais, faire tiédir l''huile d''olive avec la moitié du beurre. Y laisser fondre l''oignon et l''ail à feu doux pendant 5 à 6 minutes, en remuant, jusqu''à ce qu''ils rendent leur eau et blondissent tout juste aux bords. Verser alors le curry en poudre et le remuer une minute pleine dans le corps gras chaud : c''est la graisse et non le bouillon qui ouvre ses arômes, et une poudre jetée crue dans le liquide garderait jusqu''au bout un goût de farine d''épice."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'riz cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Riz cru', 275, 'g', 'required',
     'féculent', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oignon jaune cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Oignon jaune cru', 120, 'g', 'required',
     'aromate', false, 2);

